#!/usr/bin/env dotnet
#:property PublishAot=false

// Find the earliest Friday the 13th in the proleptic Gregorian calendar
// and count how many occur in a full 400-year cycle.

// Earliest Friday the 13th starting from 0001-01-01
var date = new DateOnly(1, 1, 13); // start on the first 13th
DateOnly? earliest = null;

while (date.Year == 1 || earliest is null)
{
    if (date.DayOfWeek == DayOfWeek.Friday)
    {
        earliest = date;
        break;
    }
    date = date.AddMonths(1);
}

Console.WriteLine($"Earliest Friday the 13th: {earliest:yyyy-MM-dd} ({earliest?.DayOfWeek})");

// Count Friday the 13ths in a full 400-year cycle (0001-01-01 to 0400-12-31)
// The Gregorian calendar repeats every 400 years.
int count = 0;
var d = new DateOnly(1, 1, 13);
while (d.Year <= 400)
{
    if (d.DayOfWeek == DayOfWeek.Friday)
        count++;
    d = d.AddMonths(1);
}

Console.WriteLine($"Friday the 13ths in a 400-year cycle: {count}");
Console.WriteLine($"Average per year: {count / 400.0:F4}");

// Bonus: distribution by month
var byMonth = new int[12];
d = new DateOnly(1, 1, 13);
while (d.Year <= 400)
{
    if (d.DayOfWeek == DayOfWeek.Friday)
        byMonth[d.Month - 1]++;
    d = d.AddMonths(1);
}

Console.WriteLine("\nDistribution by month:");
for (int m = 0; m < 12; m++)
    Console.WriteLine($"  {new DateOnly(2000, m + 1, 1):MMMM,-12} {byMonth[m],3}");

